/// 머무름 유지 시간은 주사 간격의 이 배수다.
/// 1.0이면 순환과 구분이 안 되고, 너무 길면 다른 동작으로 넘어가기 어렵다.
const DWELL_FACTOR: u32 = 3;
const DWELL_DIVISOR: u32 = 2;

